package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	Query    string   `json:"query"`
	Fields   []string `json:"fields"`
	OrderBy  string   `json:"order_by"`
	Limit    int      `json:"limit"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

func sanitizeField(field string) string {
	// Only allow alphanumeric and underscore in field names
	for _, c := range field {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_') {
			return "id"
		}
	}
	return field
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON", 400)
		return
	}

	if req.Limit <= 0 || req.Limit > 100 {
		req.Limit = 20
	}

	// Build field list - sanitized
	var fields []string
	for _, f := range req.Fields {
		fields = append(fields, sanitizeField(f))
	}
	if len(fields) == 0 {
		fields = []string{"id", "title", "description"}
	}

	// Build WHERE clause using parameterized query for the search term
	// But ORDER BY is constructed via string formatting (vulnerability)
	orderClause := "id"
	if req.OrderBy != "" {
		// Developer assumed frontend only sends valid column names
		// No sanitization on OrderBy - SQL injection possible
		orderClause = req.OrderBy
	}

	query := fmt.Sprintf(
		"SELECT %s FROM products WHERE title ILIKE $1 OR description ILIKE $1 ORDER BY %s LIMIT %d",
		strings.Join(fields, ", "),
		orderClause,
		req.Limit,
	)

	searchTerm := "%" + req.Query + "%"
	rows, err := db.Query(query, searchTerm)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var results []map[string]interface{}
	cols, _ := rows.Columns()
	for rows.Next() {
		values := make([]interface{}, len(cols))
		pointers := make([]interface{}, len(cols))
		for i := range values {
			pointers[i] = &values[i]
		}
		rows.Scan(pointers...)
		row := make(map[string]interface{})
		for i, col := range cols {
			row[col] = values[i]
		}
		results = append(results, row)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
